    static string HolidayCachePath() {
        return Path.Combine(AppBaseDir, "holidays.json");
    }

    // One parser serves both the network response and the cached file, because
    // the cache stores the source document verbatim.
    static bool TryParseHolidayJson(string json, string year, out string[] dates, out int count) {
        dates = new string[0]; count = 0;
        if (json == null || json.IndexOf("days") < 0) return false;
        System.Collections.ArrayList list = new System.Collections.ArrayList();
        int pos = 0;
        while (true) {
            int d = json.IndexOf("date", pos);
            if (d < 0) break;
            int q1 = json.IndexOf('"', d + 4);
            if (q1 < 0) break;
            int q2 = json.IndexOf('"', q1 + 1);
            if (q2 < 0) break;
            string v = json.Substring(q1 + 1, q2 - q1 - 1);
            pos = q2 + 1;
            if (v.Length != 10 || v[4] != '-') continue;
            int off = json.IndexOf("isOffDay", q2);
            if (off < 0) break;
            int t = json.IndexOf("true", off);
            if (t < 0 || t - off > 24) continue;          // false, or malformed
            list.Add(v.Substring(0, 4) + v.Substring(5, 2) + v.Substring(8, 2));
        }
        if (list.Count == 0) return false;
        dates = (string[])list.ToArray(typeof(string));
        count = dates.Length;
        return true;
    }

    static void StoreHolidayDates(string[] dates, string year) {
        System.Collections.Hashtable h = new System.Collections.Hashtable();
        for (int i = 0; i < dates.Length; i++) { h[dates[i]] = true; }
        lock (HolidayLock) { _holidayDates = h; _holidayYear = year; }
    }

    static void ClearHolidayTable() {
        lock (HolidayLock) {
            _holidayDates = new System.Collections.Hashtable();
            _holidayYear = "";
        }
    }

    static void LoadHolidayBuiltIn(string year) {
        System.Collections.ArrayList list = new System.Collections.ArrayList();
        for (int i = 0; i < HolidayBuiltIn.Length; i++) {
            if (HolidayBuiltIn[i].StartsWith(year)) list.Add(HolidayBuiltIn[i]);
        }
        if (list.Count > 0) {
            StoreHolidayDates((string[])list.ToArray(typeof(string)), year);
        } else {
            // No table for this year (e.g. the clock rolled into a year whose
            // announcement is not out yet). Keeping the PREVIOUS year's table
            // would leave _holidayYear on the old value and answer from a stale
            // calendar, so clear it and let the weekday rule apply.
            ClearHolidayTable();
        }
    }

    static void LoadHolidayCache() {
        try {
            string p = HolidayCachePath();
            if (!File.Exists(p)) return;
            string s = File.ReadAllText(p);
            int i = s.IndexOf("year");
            string y = "";
            if (i >= 0) {
                int colon = s.IndexOf(':', i);
                if (colon > 0) {
                    int e = colon + 1;
                    while (e < s.Length && (s[e] == ' ' || s[e] == (char)9)) e++;
                    int b = e;
                    while (b < s.Length && s[b] >= '0' && s[b] <= '9') b++;
                    if (b - e == 4) y = s.Substring(e, 4);
                }
            }
            string[] dates; int n;
            if (y.Length == 4 && TryParseHolidayJson(s, y, out dates, out n)) {
                StoreHolidayDates(dates, y);
                LogHoliday("holidays: " + n + " days for " + y + " from cache");
            }
        } catch { }
    }

    static string FetchHolidayJson(string year, int timeoutMs) {
        string[] urls = new string[] {
            "https://raw.githubusercontent.com/NateScarlet/holiday-cn/master/" + year + ".json",
            "https://timor.tech/api/holiday/year/" + year
        };
        for (int i = 0; i < urls.Length; i++) {
            try {
                using (HttpClient c = new HttpClient()) {
                    c.Timeout = TimeSpan.FromMilliseconds(timeoutMs);
                    c.DefaultRequestHeaders.Add("User-Agent", "dsh-pet");
                    string body = c.GetStringAsync(urls[i]).Result;
                    if (body != null && body.Length > 40) return body;
                }
            } catch { }
        }
        return null;
    }

    static void RefreshHolidaysOnce(string year) {
        string json = FetchHolidayJson(year, 10000);
        if (json == null) {
            LogHoliday("holidays: no source reachable for " + year + " - keeping current table");
            return;
        }
        string[] dates; int n;
        if (!TryParseHolidayJson(json, year, out dates, out n)) {
            LogHoliday("holidays: " + year + " has no published days yet - weekday rule applies");
            return;
        }
        StoreHolidayDates(dates, year);
        try { File.WriteAllText(HolidayCachePath(), json); } catch { }
        LogHoliday("holidays: " + n + " days for " + year + " (network)");
    }

    // Called every tick; the body runs once a day.
    void MaybeRefreshHolidays() {
        DateTime bj = CloudBeijing();
        if (bj.Date == _holidayDayChecked) return;
        _holidayDayChecked = bj.Date;
        string year = bj.Year.ToString("0000");
        LoadHolidayBuiltIn(year);
        LoadHolidayCache();
        if ((bj - _holidayLastTry).TotalHours >= HolidayRefreshHours) {
            _holidayLastTry = bj;
            string y = year;
            try {
                Task.Factory.StartNew(delegate { RefreshHolidaysOnce(y); });
            } catch { }
        }
    }

    static bool IsHoliday(DateTime bj) {
        bool hit;
        lock (HolidayLock) {
            if (_holidayYear != bj.Year.ToString("0000")) return false;   // no data -> weekday rule
            hit = _holidayDates[bj.ToString("yyyyMMdd")] != null;
        }
        return hit;
    }

    bool OffPeakNow() { return !IsPeakAt(CloudBeijing()); }

    // Time until the tariff flips, and which way. The switch points are 09:00 /
    // 12:00 / 14:00 / 18:00 on weekdays; walking 8 days at 15-minute steps always
    // reaches a change (Friday 18:00 -> Monday 09:00 is the longest gap, 63 h).
    //
    // The scan MUST start at TODAY 00:15, not at tomorrow: from 06:00 the next
    // switch is today's 09:00, and starting tomorrow reported 75 h instead of 3 h.
    // 00:15 (not 00:00) keeps the first candidate strictly in the future, so a
    // boundary moment reports the NEXT switch rather than itself.
    TimeSpan UntilSwitch(out bool toPeak) {
        DateTime bj = CloudBeijing();
        bool nowPeak = IsPeakAt(bj);
        DateTime d = bj.Date;
        for (int day = 0; day <= 8; day++) {
            for (int q = 1; q < 96; q++) {
                DateTime c = d.AddMinutes(q * 15);
                if (c <= bj) continue;
                if (IsPeakAt(c) == nowPeak) continue;
                toPeak = !nowPeak;
                TimeSpan left = c - bj;
                if (left < TimeSpan.Zero) left = TimeSpan.Zero;
                return left;
            }
            d = d.AddDays(1);
        }
        toPeak = !nowPeak;
        return TimeSpan.Zero;
    }

    // Three lines on the tablet: the clock, who is on duty, and today's spend.
    Bitmap BuildPanelPeak(int pw, int ph) {
        string key = "peak|" + CloudBeijing().ToString("HH:mm:ss") + "|" + OffPeakNow() + "|" +
                      _todayUsed.ToString("0.00", CultureInfo.InvariantCulture);
        if (_panelCacheValid && _panelCache != null && _panelCacheW == pw && _panelCacheH == ph &&
            _panelCacheText == key) return _panelCache;
        if (_panelCache != null) { _panelCache.Dispose(); }
        _panelCache = null; _panelCacheValid = false;
        Bitmap panel = new Bitmap(pw, ph, PixelFormat.Format32bppArgb);
        using (Graphics g = Graphics.FromImage(panel)) {
            g.SmoothingMode = SmoothingMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.AntiAlias;
            float W = pw, H = ph;
            using (StringFormat sf = new StringFormat()) {
                sf.Alignment = StringAlignment.Center;
                sf.LineAlignment = StringAlignment.Center;
                bool toPeak;
                TimeSpan left = UntilSwitch(out toPeak);
                string cd = ((int)left.TotalHours).ToString("0") + ":" +
                            left.Minutes.ToString("00") + ":" + left.Seconds.ToString("00");
                string[] lines = new string[] {
                    CloudBeijing().ToString("HH:mm:ss"),
                    OffPeakNow() ? S_PEAK_OFF : S_PEAK_PEAK,
                    (toPeak ? S_TO_PEAK : S_TO_OFF) + " " + cd
                };
                float[] frac = new float[] { 0.10f, 0.38f, 0.66f };
                float[] size = new float[] { 0.26f, 0.26f, 0.18f };
                for (int i = 0; i < 3; i++) {
                    // Colour carries the tariff too: the off-peak line reads green, the peak line warm,
                    // so the state is legible at a glance and does not rely on reading the name.
                    Color ink = i == 1 ? (OffPeakNow() ? Color.FromArgb(255, 150, 226, 170)
                                                        : Color.FromArgb(255, 240, 190, 120))
                                       : Color.FromArgb(255, 236, 242, 252);
                    using (Font f = new Font("Microsoft YaHei UI", H * size[i], FontStyle.Bold,
                                             GraphicsUnit.Pixel))
                    using (Brush sh = new SolidBrush(Color.FromArgb(160, 0, 0, 0)))
                    using (Brush b = new SolidBrush(ink)) {
                        RectangleF r = new RectangleF(0, H * frac[i], W, H * 0.3f);
                        g.DrawString(lines[i], f, sh,
                                     new RectangleF(r.X + 1.5f, r.Y + 1.5f, r.Width, r.Height), sf);
                        g.DrawString(lines[i], f, b, r, sf);
                    }
                }
            }
        }
        _panelCache = panel; _panelCacheValid = true;
        _panelCacheW = pw; _panelCacheH = ph; _panelCacheText = key;
        return panel;
    }

    // The old behaviour: the digits were always drawn at H*0.48 with no width check,
    // which is what let "100.00" run off the tablet. Kept only so --panelcheck can
    // show the difference side by side.
    Bitmap BuildPanelFixed(int pw, int ph, string txt) {
        Bitmap panel = new Bitmap(pw, ph, PixelFormat.Format32bppArgb);
        using (Graphics g = Graphics.FromImage(panel)) {
            g.TextRenderingHint = TextRenderingHint.AntiAlias;
            float W = pw, H = ph;
            using (Font fb = new Font("Arial", H * 0.48f, FontStyle.Bold, GraphicsUnit.Pixel))
            using (Brush bb = new SolidBrush(Color.FromArgb(255, 240, 246, 255))) {
                SizeF sb = g.MeasureString(txt, fb);
                g.DrawString(txt, fb, bb, (W - sb.Width) / 2f, H * 0.44f);
            }
        }
        return panel;
    }

    Bitmap BuildPanel(int pw, int ph, string txt) { return BuildPanel(pw, ph, txt, false); }

    // noCache is for callers that own the lifetime of what they get back. --panelcheck
    // renders a sheet of ten different panels inside using blocks; handing those the
    // cached instance would leave the cache pointing at a disposed bitmap and the next
    // real frame would draw from it.
    Bitmap BuildPanel(int pw, int ph, string txt, bool noCache) {
        // Reuse the previous panel when nothing it depends on changed. The balance is
        // what usually changes, and it changes once per cue - not once per frame.
        if (!noCache && _panelCacheValid && _panelCache != null &&
            _panelCacheW == pw && _panelCacheH == ph &&
            _panelCacheText == txt && _panelCacheFx == _fx[0]) {
            return _panelCache;
        }
        if (!noCache && _panelCache != null) { _panelCache.Dispose(); }
        _panelCache = null; _panelCacheValid = false;
        Bitmap panel = new Bitmap(pw, ph, PixelFormat.Format32bppArgb);
        using (Graphics g = Graphics.FromImage(panel)) {
            g.SmoothingMode = SmoothingMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.AntiAlias;

            float W = pw, H = ph;
            using (StringFormat sf = new StringFormat()) {
                sf.Alignment = StringAlignment.Center;
                sf.LineAlignment = StringAlignment.Center;

                float fLabel = H * 0.21f;
                using (Font f = new Font("Microsoft YaHei UI", fLabel, FontStyle.Bold, GraphicsUnit.Pixel))
                using (Brush shadow = new SolidBrush(Color.FromArgb(150, 0, 0, 0)))
                using (Brush b = new SolidBrush(Color.FromArgb(235, 158, 182, 224))) {
                    RectangleF lr = new RectangleF(0, H * 0.04f, W, fLabel * 1.5f);
                    g.DrawString(S_LABEL, f, shadow, new RectangleF(lr.X + 1.5f, lr.Y + 1.5f, lr.Width, lr.Height), sf);
                    g.DrawString(S_LABEL, f, b, lr, sf);
                }

                float fCur = H * 0.27f;
                using (Font fc = new Font("Microsoft YaHei UI", fCur, FontStyle.Bold, GraphicsUnit.Pixel))
                using (Brush sh = new SolidBrush(Color.FromArgb(160, 0, 0, 0)))
                using (Brush bb = new SolidBrush(Color.FromArgb(255, 240, 246, 255)))
                using (Brush bc = new SolidBrush(Color.FromArgb(235, 158, 184, 230))) {
                    SizeF sc = g.MeasureString("\u00A5", fc);

                    // The digits get whatever width is left after the sign and the
                    // margins. The panel itself cannot grow (its size is the tablet's
                    // screen), so a longer number is drawn SMALLER instead of running
                    // off the tablet - "100.00" used to spill over the frame. The sign
                    // and the label keep their size, as asked.
                    float fBal = DigitSizeFor(g, W, H, txt, sc.Width);
                    SizeF sb, sbFull;
                    using (Font f0 = new Font("Arial", H * 0.48f, FontStyle.Bold, GraphicsUnit.Pixel))
                        sbFull = g.MeasureString(txt, f0);

                    using (Font fb = new Font("Arial", fBal, FontStyle.Bold, GraphicsUnit.Pixel)) {
                        sb = g.MeasureString(txt, fb);
                        // NUMBER FIRST, then the sign: "55 <yuan>", not "<yuan> 55". (The
                        // currency glyph is written as a \u escape in the code below; this
                        // comment says "<yuan>" because this file must stay pure ASCII.)
                        //
                        // That is the user's reading order, and it matches how every other amount
                        // in this program is written (the floating numbers are "-1.00 <yuan>"). The
                        // tablet used to lead with the sign, which reads as a prefix in English
                        // but not as the trailing unit the rest of the UI uses.
                        float total = sb.Width + sc.Width;
                        float left = (W - total) / 2f;
                        // Keep the block's vertical CENTRE where it was: a smaller
                        // number would otherwise sit lower than the old one.
                        float top = H * 0.44f + (sbFull.Height - sb.Height) * 0.5f;
                        g.DrawString(txt, fb, sh, left + 1.5f, top + 1.5f);
                        g.DrawString("\u00A5", fc, sh, left + sb.Width + 1.5f, top + sb.Height * 0.24f + 1.5f);
                        g.DrawString(txt, fb, bb, left, top);
                        g.DrawString("\u00A5", fc, bc, left + sb.Width, top + sb.Height * 0.24f);
                    }
                }
            }
        }
        // Publish as the cache. There is exactly one live panel at a time, and it is
        // this one - the previous one was disposed on the way in.
        if (!noCache) {
            _panelCache = panel;
            _panelCacheValid = true;
            _panelCacheW = pw; _panelCacheH = ph;
            _panelCacheText = txt; _panelCacheFx = _fx[0];
        }
        return panel;
    }

    void DrawScreen() {
        int pw, ph;
        PanelSize(out pw, out ph);
        if (pw < 8 || ph < 8) return;

        long tPan = _perfPhases ? Stopwatch.GetTimestamp() : 0;
        Bitmap panel = BuildPanel(pw, ph);
        if (_perfPhases) { _phPanelBuild += Ms(tPan); tPan = Stopwatch.GetTimestamp(); }
        try {
            using (Graphics g = Graphics.FromImage(_canvas)) {
                g.SmoothingMode = SmoothingMode.HighQuality;
                g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = PixelOffsetMode.HighQuality;
                PointF[] dest = new PointF[3];
                float bx = (float)(_offX + _shakeX), by = (float)(_offY + _shakeY);
                // The three vertices that define the parallelogram the panel is mapped onto.
                //
                // The quad's four corners run 0=top-left, 1=top-right, 2=bottom-right,
                // 3=bottom-left of the tablet. Mirroring the sprite reverses the x of every
                // vertex, which turns that ring into top-right, top-left, bottom-left,
                // bottom-right - so vertex 0 becomes the TOP-RIGHT corner and 3 becomes the
                // BOTTOM-RIGHT one. Every index changes meaning.
                //
                // The three points must therefore be taken as (1, 0, 2) when mirrored, not
                // (1, 0, 3). Using 3 there was the bug the user saw: the three points no longer
                // describe the tablet's parallelogram, so the panel was sheared across her leg
                // AND the cached panel rect no longer matched where it landed. (1, 0, 2) keeps
                // the winding the same as the unmirrored (0, 1, 3), so the glyphs stay upright.
                int iA = _snapRight ? 1 : 0;      // top-left  corner
                int iB = _snapRight ? 0 : 1;      // top-right corner
                int iC = _snapRight ? 2 : 3;      // bottom-left corner
                // The readout is ON her tablet, so it has to bounce with her. The words used to
                // sit perfectly still while she flinched, which is the "the text does not bounce
                // along" report. Squashed VERTICALLY about the same anchor the sprite uses: only
                // the glyphs' y changes, so the panel keeps its shape on the tablet and the text
                // neither stretches nor tilts. Squashing x as well would scale the whole panel
                // about her feet, which is not what the flinch does to her.
                dest[0] = new PointF((float)_fx[iA] + bx, SquashY((float)_fy[iA] + by));
                dest[1] = new PointF((float)_fx[iB] + bx, SquashY((float)_fy[iB] + by));
                dest[2] = new PointF((float)_fx[iC] + bx, SquashY((float)_fy[iC] + by));
                g.DrawImage(panel, dest);
            }
        } finally {
            if (_perfPhases) { _phPanelDraw += Ms(tPan); }
            // Do NOT dispose a cached panel here: BuildPanel hands back the shared
            // instance, and disposing it would leave the cache pointing at a dead
            // bitmap ("Parameter is not valid" from Image.RawFormat on the next frame).
            if (!ReferenceEquals(panel, _panelCache)) panel.Dispose();
        }
    }

    // Where a point at canvas row y ends up once the head-squash has been applied.
    //
    // The transform the sprite is drawn with is a vertical scale about the widget's bottom edge
    // (see PaintWidgetArt), so anything that is meant to look like it is part of her - the tablet
    // readout, her floating numbers, the offline dot - has to go through the same mapping or it
    // sits still while she moves. Vertical only, deliberately: squashing x too would scale the
    // whole panel about her feet instead of letting it ride on the tablet.
    float SquashY(float y) {
        // The head pat deforms her through a DIFFERENT pair of variables, so this had to learn about
        // it: the pat writes _patSquash / _patShiftY rather than _squashScale, because _squashScale is
        // also what the erase mask is stamped with and must keep its pot-bounce meaning. The result was
        // that during a pat she compressed and the floating numbers did not - they hung in the air,
        // which is exactly the "detached" look this function exists to prevent.
        if (_patActive) {
            // CANVAS coordinates, because that is what BOTH callers already pass:
            //   DrawFloater: fl.Y ... + _shakeY + _offY
            //   DrawScreen : _fy[i] + _shakeY + _offY
            // Converting the anchor into that space instead of changing the callers means the two
            // cannot drift apart, and it keeps a single definition of the pivot.
            //
            // The pivot is her feet plus the pat's slide: the sprite is drawn with a vertical scale
            // about exactly that screen row, so any element that belongs to her must use the same one.
            // Using a widget-space anchor here - a thousand pixels away from where the values live -
            // is what squashed the tablet about the wrong point, and it moved 2 px on the frame she
            // moved 66.
            int anchor = _offY + _h + _patShiftY;
            return (float)((y - anchor) * _patSquash + anchor);
        }
        if (!_squashOn) return y;
        return (float)((y - _squashAnchorY) * _squashScale + _squashAnchorY);
    }

    // offline indicator: a small dot, so the screen keeps showing only the
    // label and the number
    void DrawAlert() {
        using (Graphics g = Graphics.FromImage(_canvas)) {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            float r = Math.Max(2.5f, (float)(_h * 0.032));
            float cx = (float)(_fx[1] + _fx[2]) / 2f + (float)_shakeX + _offX;
            // On the tablet, so it bounces with her like the readout does.
            float cy = SquashY((float)(_fy[1] + _fy[2]) / 2f + (float)(_h * 0.05) + (float)_shakeY + (float)_offY);
            using (Brush b = new SolidBrush(Color.FromArgb(235, 228, 62, 52)))
                g.FillEllipse(b, cx - r, cy - r, r * 2, r * 2);
            using (Pen p = new Pen(Color.FromArgb(210, 255, 255, 255), Math.Max(1f, r * 0.3f)))
                g.DrawEllipse(p, cx - r, cy - r, r * 2, r * 2);
        }
    }

    void DrawFloater(Floater fl, Buf dst) {
        double t = fl.T / fl.Dur;
        float em = (float)Math.Max(13.0, 34.0 * _scale);
        float pop = t < 0.18 ? (float)(0.62 + 0.38 * (t / 0.18)) : 1f;
        double alpha = t < 0.55 ? 1.0 : (1 - (t - 0.55) / 0.45);
        if (alpha <= 0) return;

        Bitmap bmp = MakeFloaterBitmap(fl.Text, em);
        try {
            Buf src = new Buf(bmp);
            try {
                byte[] p = dst.P, sp = src.P;
                int ds = dst.Stride, ss = src.Stride;
                int w = (int)(src.W * pop), h = (int)(src.H * pop);
                // the shake offset is applied here so the number shakes together
                // with the character instead of hanging in place
                int x0 = fl.X + (int)Math.Round(fl.Jitter * Math.Sin(t * 9)) + _shakeX + _offX;
                // ...and the squash offset too, for the same reason: a number that hangs in the air
                // while she flinches reads as detached from her. These numbers are born at her head
                // and rise, so they belong to her for the whole animation.
                int y0 = (int)Math.Round(SquashY(fl.Y - (int)Math.Round(t * em * 2.7) + _shakeY + _offY));
                // Clip against the LOCKED RECT (canvas coordinates), not the widget:
                // x0/y0 already include _offX/_offY, so testing them against _w/_h
                // (~454) threw every floater away and the damage numbers vanished.
                int rx = dst.R.X, ry = dst.R.Y;
                for (int yy = 0; yy < h; yy++) {
                    int syy = (int)(yy / pop); if (syy >= src.H) break;
                    int ty = y0 + yy - ry; if (ty < 0 || ty >= dst.H) continue;
                    for (int xx = 0; xx < w; xx++) {
                        int sxx = (int)(xx / pop); if (sxx >= src.W) break;
                        int tx = x0 + xx - rx; if (tx < 0 || tx >= dst.W) continue;
                        int si = syy * ss + sxx * 4;
                        int sa = sp[si + 3]; if (sa == 0) continue;
                        Cs.Blend(p, ty * ds + tx * 4, sp[si + 2], sp[si + 1], sp[si], sa / 255.0 * alpha);
                    }
                }
            } finally { src.Dispose(); }
        } finally { bmp.Dispose(); }
    }

    Bitmap MakeFloaterBitmap(string text, float em) {
        // "+x.xx" is money coming back, so it reads green; everything else is a
        // charge and stays red. Decided from the text so every caller gets it.
        bool gain = text.Length > 0 && text[0] == '+';
        Color fillCol = gain ? Color.FromArgb(255, 58, 220, 90) : Color.FromArgb(255, 255, 72, 60);
        Color edgeCol = gain ? Color.FromArgb(255, 8, 85, 28) : Color.FromArgb(255, 92, 8, 8);
        using (Font f = new Font("Arial", em, FontStyle.Bold, GraphicsUnit.Pixel)) {
            Size sz = TextRenderer.MeasureText(text, f, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPadding);
            int pad = (int)(em * 0.45f);
            Bitmap bmp = new Bitmap(Math.Max(4, sz.Width + pad * 2), Math.Max(4, sz.Height + pad * 2),
                                    PixelFormat.Format32bppArgb);
            using (Graphics g = Graphics.FromImage(bmp)) {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.TextRenderingHint = TextRenderingHint.AntiAlias;
                using (GraphicsPath path = new GraphicsPath()) {
                    path.AddString(text, f.FontFamily, (int)FontStyle.Bold, em, new PointF(pad, pad),
                                   StringFormat.GenericTypographic);
                    using (Pen outline = new Pen(edgeCol, em * 0.16f)) {
                        outline.LineJoin = LineJoin.Round;
                        g.DrawPath(outline, path);
                    }
                    using (Brush fill = new SolidBrush(fillCol))
                        g.FillPath(fill, path);
                }
            }
            return bmp;
        }
    }

    // ---------------------------------------------------------------- tick ---

    void OnTick() {
        // Always stamped: LastTickMs feeds the runtime ledger, and leaving it 0 made
        // Ms(0) report "time since boot" - a 38,000,000 ms tick_avg in the log.
        long tTick0 = Stopwatch.GetTimestamp();
        long tPh0 = tTick0;
        try {
            long tHol = _perfPhases ? Stopwatch.GetTimestamp() : 0;
            MaybeRefreshHolidays();
            if (_perfPhases) { _phHoliday += Ms(tHol); }
            long tPD = _perfPhases ? Stopwatch.GetTimestamp() : 0;
            if (_pollWant != 0) { int want = _pollWant; _pollWant = 0; PollNow(want == 2); }
            if (_perfPhases) { _phPollDrain += Ms(tPD); }
            if (_perfPhases) { _phPoll += Ms(tPh0); tPh0 = Stopwatch.GetTimestamp(); }

            double dt = _timer.Interval / 1000.0;
            bool anim = false;

            if (_snapping) {
                _snapT += dt / 0.16;
                if (_snapT >= 1) { _offX = _snapTo.X; _offY = _snapTo.Y; _snapping = false; }
                else {
                    double e = 1 - Math.Pow(1 - _snapT, 3);
                    _offX = (int)Math.Round(_snapFrom.X + (_snapTo.X - _snapFrom.X) * e);
                    _offY = (int)Math.Round(_snapFrom.Y + (_snapTo.Y - _snapFrom.Y) * e);
                }
                RenderToCanvas();
                PushLayer();
            }

            _lastCueAmount = 0;              // diagnostics: what fired this frame
            DrainBankedBalance();            // apply any reading that arrived
            if (_perfPhases) { _phDrain += Ms(tPh0); tPh0 = Stopwatch.GetTimestamp(); }

            if (_dueGap > 0) _dueGap -= dt;

            // A freshly fed bowl buys a short pause before any spending animation.
            // A rehearsal credits money that the cloud never had, so the very next
            // poll books it straight back as debt and the girl starts losing health
            // the instant the hearts appear. The delay is purely for demonstration:
            // the debt still accumulates, it just waits.
            if (_cueGrace > 0) _cueGrace -= dt;
            else _cueGrace = 0;
            // Head-squash timer. Runs to HeadSquashDur and stops; the renderer treats
            // "at duration" as "no animation".
            if (_headSquashT < HeadSquashDur) {
                _headSquashT += dt;
                if (_headSquashT > HeadSquashDur) _headSquashT = HeadSquashDur;
                anim = true;
            }

            // Head pat: advances its own clock and reports whether it changed anything, so the widget
            // keeps repainting while the hand is on screen. Without anim=true here the frame the pat
            // starts would be the only one drawn.
            //
            // dt is passed in MILLISECONDS: the timer's dt above is in seconds and feeding that to a
            // counter compared against PAT_HOLD_MS (200) is what stopped the pat ever firing.
            {
                double patBefore = _patT;
                bool patWasActive = _patActive;
                TickPat(_timer.Interval);
                if (_patActive || patWasActive || _patT != patBefore) anim = true;
            }

            // The ONLY place the printed number moves: one cent per cue, never
            // more, and never without a cue. The debt is re-derived every time a
            // reading lands, so a reading arriving mid-cue can never strand it.
            //
            // While a bowl is out, nothing is deducted at all: an outstanding charge
            // waits until the bowl has been eaten. The debt keeps accumulating in
            // _pending - only the animation and the drop are held back.
            double take = 0;
            if (!_bowlPending() && _dueGap <= 0 && _pendingStep <= 0 && _cueGrace <= 0) {
                if (_pending >= StepYuan - 1e-9) take = StepYuan;
                else if (_pending > 1e-9) take = Math.Round(_pending, 2);   // sub-cent sliver
            }
            if (take > 0) {
                if (DiagBalance) Log("TAKE take=" + take.ToString("0.0000") +
                                     " pendingBefore=" + _pending.ToString("0.0000") +
                                     " dueGap=" + _dueGap.ToString("0.000"));
                _pending = Math.Round(_pending - take, 4);
                if (_pending < 1e-9) _pending = 0;
                _bookedAt = Math.Round(_bookedAt - take, 4);
                _bookedBal = Math.Round(_bookedBal - take, 4);
                _pendingStep = take;
                _dueGap = CueGapSec;
            }

            // The cue itself fires once the previous floater has finished rising:
            // The cue fires as soon as its slot is due. It deliberately does NOT
            // wait for the previous number to finish flying: with a 0.2s rhythm
            // that wait would stretch every cue to over a second. The numbers
            // stack upwards instead, comet-style, so a run of cues still reads
            // clearly.
            if (_pendingStep > 0) {
                _lastCueAmount = _pendingStep;
                MakeTick(_pendingStep, false);
                _pendingStep = 0;
                anim = true;
            }

            // Rehearsal run: same rhythm as real charges, so a custom amount shows
            // exactly what a burst of real spending looks like. The printed number
            // walks down; the books stay untouched.
            //
            // _cueGrace is checked here for the SAME reason as in the real path above:
            // a bowl that has just been eaten buys a quiet period, and leaving the
            // guard out let a queued rehearsal fire straight through it. That is the
            // reported "the bowl is eaten and she immediately grimaces and drains".
            if (_demoLeft > 0 && _pendingStep <= 0 && _dueGap <= 0 && _cueGrace <= 0) {
                _lastCueAmount = _demoAmount;
                MakeTick(_demoAmount, true);
                _demoLeft--;
                _dueGap = CueGapSec;
                anim = true;
            }
            for (int i = _hits.Count - 1; i >= 0; i--) {
                _hits[i].T += dt; anim = true;
                if (_hits[i].Done) _hits.RemoveAt(i);
            }
            for (int i = _floaters.Count - 1; i >= 0; i--) {
                _floaters[i].T += dt; anim = true;
                if (_floaters[i].Done) _floaters.RemoveAt(i);
            }

            // Top-up bowl, its hearts and the linear recovery of the readout.
            // Sample the cursor BEFORE stepping: a release that lands between two
            // ticks still throws with the speed of the frame that just ran.
            if (_riceGrab != null) ThrowSample(dt);
            // Peak/off-peak readout hold. It stays up while the pointer is on her or a button is held,
            // and reverts 5 s after that stops - but a charge in progress postpones the revert, because
            // switching the tablet mid-animation would cut the number the user is watching.
            // "On screen" is not a useful test in a screen-sized window - the cursor is always on the
            // screen. What the user means by keeping it up is that they are still interacting with her,
            // which is the same test the right-click menu and the pat already use.
            {
                // Client-area coordinates: the window is screen-sized, so client == canvas, and that is
                // exactly what GirlPixelSolid (and every mouse handler here) expects. Subtracting the
                // widget offset as well shifted the probe off her, which pinned "engaged" true and
                // stopped the countdown from ever finishing - the readout then only went away when a
                // click forced a repaint.
                Point cur = Cursor.Position;
                _mouseInside = GirlPixelSolid(cur.X - Left, cur.Y - Top);
            }
            // The clock has to tick. Nothing else marks the panel dirty while it is up, so without
            // this the time only changed when some other action forced a repaint - exactly the
            // "the time is not live" report.
            if (_peakMode) {
                int sec = CloudBeijing().Second;
                if (sec != _peakSec) {
                    _peakSec = sec; _panelCacheValid = false; _dirty = true;
                    // _forceFullFill, not a dirty rectangle.
                    //
                    // haveDirty = _forceFullFill || (dirty rect non-empty), so this is guaranteed to
                    // push regardless of whether the rectangle was computed correctly and regardless of
                    // RenderToCanvas clearing it. The dirty-rectangle route looked fine under
                    // --peaktick (manual tick loop) but the screen never moved under the real timer, so
                    // it depended on a precondition that does not hold on the shipped path. This one has
                    // no precondition to get wrong; the cost is one full-canvas composite per second,
                    // and only while the panel is up.
                    _forceFullFill = true;
                    Invalidate();
                }
            }

            // No automatic revert. The user asked for a plain toggle - double click out, double click
            // back - after the timed version proved unreliable. A toggle has no clock, no pointer
            // tracking and no interaction with a charge in flight, so there is nothing left to get
            // wrong; and it is easier to explain.

            long tPh = _perfPhases ? Stopwatch.GetTimestamp() : 0;
            UpdateRice(dt);
            if (_perfPhases) { _phRicePhys += Ms(tPh); tPh = Stopwatch.GetTimestamp(); }
            if (_rices.Count > 0 || _hearts.Count > 0) anim = true;

            // Mood for this frame. Runs after the physics and the cue bookkeeping so
            // it sees the same state the renderer is about to draw.
            UpdateExpression(dt);
            if (_perfPhases) { _phExpr += Ms(tPh); tPh = Stopwatch.GetTimestamp(); }
            // Radar AFTER the mood: the lock only exists while she is aloof, and the
            // magnet moves the bowl, so it has to run after UpdateRice too.
            UpdateRadar(dt);
            if (_perfPhases) { _phRadar += Ms(tPh); tPh = Stopwatch.GetTimestamp(); }

            // Mark the tablet AFTER the re-render (see the note where _peakPush is set) and before the
            // push, so the new digits actually reach the screen.
            // A parked rectangle must not wait for the next unrelated change: ask for a
            // composite every tick until it goes out. The canvas already holds the right pixels,
            // so only the push is needed - re-rendering here would repaint her box for nothing.
            if (anim || _dirty || !_deferRect.IsEmpty) {
                if (anim || _dirty) RenderToCanvas();
                PushLayer();
            }
            if (_perfPhases) { _phTickTail += Ms(tPh); }
        } catch (Exception ex) { Log("tick: " + ex); }
        LastTickMs = Ms(tTick0);
        if (_perfLog) {
            _plTick += LastTickMs;
            _plRender += LastRenderMs;
            _plPush += LastPushMs;
            // An average hides the frames that actually cause the stutter.
            if (LastTickMs > _plTickMax) _plTickMax = LastTickMs;
            if (LastRenderMs > _plRenderMax) _plRenderMax = LastRenderMs;
            if (LastPushMs > _plPushMax) _plPushMax = LastPushMs;
            _plFrames++;
            if (LastPushMs > 0) _plPushes++;
            double nowSec = NowSec();
            if (_plLast <= 0) _plLast = nowSec;
            if (nowSec - _plLast >= 1.0 && _plFrames > 0) {
                // Push is reported two ways: averaged over frames (real per-frame cost,
                // which is what the user feels) and summed over the second (total work).
                Log("PERF frames=" + _plFrames +
                    " tick_avg=" + (_plTick / _plFrames).ToString("0.00") +
                    " render_avg=" + (_plRender / _plFrames).ToString("0.00") +
                    " push_avg=" + (_plPush / _plFrames).ToString("0.00") +
                    " pushes=" + _plPushes +
                    " push_sum=" + _plPush.ToString("0.0") +
                    // Area actually converted per push: this is the number that says
                    // whether a stutter is about pixels or about something else.
                    " fillPx=" + (_plFillPx / Math.Max(1, _plPushes)).ToString("0") +
                    " fillMs=" + _plFillMs.ToString("0.0") +
                    // The widest/tallest rectangle of the second exposes which path made
                    // a huge push: a full-canvas rect means the whole-canvas branch ran.
                    " maxRect=" + _plMaxRw + "x" + _plMaxRh +
                    " full=" + _plFullFills +
                    " MAX tick=" + _plTickMax.ToString("0.0") +
                    " render=" + _plRenderMax.ToString("0.0") +
                    " push=" + _plPushMax.ToString("0.0") +
                    " bigMark=" + _plMarkW + "x" + _plMarkH + "@" + _plMarkX + "," + _plMarkY +
                    " lay=" + _plRelayout + "/" + _plExprHit + "h" + _plExprMiss + "m" +
                    " layMs=" + _plRelayoutMs.ToString("0.0") +
                    " layMax=" + _plRelayoutMax.ToString("0.0") +
                    " cvRebuild=" + _plCanvasRebuilt +
                    " dib=" + _plDibOk + " hbm=" + _plHbitmap +
                    " hbmMs=" + _plHbitmapMs.ToString("0.0") +
                    " ulw=" + (_ulwBlt ? 1 : 0) +
                    " budget=" + _timer.Interval +
                    " every=" + _pushEvery + " skip=" + _pushSkip +
                    // Time spent inside mciSendString this second. This is the number that
                    // proves the sound path got cheap (or did not).
                    " snd=" + SoundPool.SendCount + "/" + SoundPool.SendMs.ToString("0.0") + "ms");
                _plTick = 0; _plRender = 0; _plPush = 0; _plFrames = 0; _plPushes = 0;
                Log(PhaseReport(_plFrames));
                ResetPhases();                  // else the next report averages the session
                _plFillPx = 0; _plFillMs = 0; _plMaxRw = 0; _plMaxRh = 0; _plFullFills = 0;
                _plDibOk = 0; _plHbitmap = 0; _plHbitmapMs = 0;
                _plRelayout = 0; _plExprHit = 0; _plExprMiss = 0; _plRelayoutMs = 0;
                _plRelayoutMax = 0; _plCanvasRebuilt = 0;
                _plMarkBig = 0; _plMarkW = 0; _plMarkH = 0; _plMarkX = 0; _plMarkY = 0;
                _plTickMax = 0; _plRenderMax = 0; _plPushMax = 0;
                SoundPool.SendMs = 0; SoundPool.SendCount = 0;
                _plLast = nowSec;
            }
        }
    }

    // fromTest: the menu / tray "test one charge" cue only pretends to spend.
    // It plays the animation and drops the printed number through _testOffset
    // while leaving _realBal and the step yardstick alone, so a later balance
    // refresh neither corrects the number back up nor mistakes the rehearsal for
    // money actually spent. There is deliberately no cap on the offset: capping
    // it used to freeze the number after ten cues. The printed value clamps at
    // zero instead, and any real spending clears the offset.
    void MakeTick(double amount, bool fromTest) {
        // Cap the simultaneous hurt overlays. Real charges are already capped by
        // the tick loop, but repeatedly clicking "test one charge" used to stack
        // an unbounded number of them and each one added its own shake, which
        // added up to a sprite flying across the screen.
        // NOT counted here. "Today's spend" is derived from the balance the server reports (see
        // NoteBalanceForSpend); the amount this animation was called with is a nominal per-cue figure,
        // not the bill. Counting it made the readout far too small.
        // The number always moves. Everything else about a charge - the hurt overlay, the shake, the
        // floating figure and the sound - is the "hurt" feature, and is skipped when it is off.
        // The balance itself is applied by the caller, so turning this off really does mean "the
        // value changes and nothing else happens".
        if (!_fxHurt) {
            if (fromTest) _testOffset = Math.Round(_testOffset + amount, 4);
            else _testOffset = 0;
            _dirty = true;
            return;
        }
        if (_hits.Count < 3) _hits.Add(new Hit());
        if (fromTest) {
            _testOffset = Math.Round(_testOffset + amount, 4);
        } else {
            _testOffset = 0;                         // real movement clears rehearsals
        }
        Floater fl = new Floater();
        fl.Text = "-" + amount.ToString("0.####", CultureInfo.InvariantCulture);
        fl.X = _headX - (int)(_w * 0.06);
        // Cascade: each number that is still in the air pushes the next one up, so
        // a fast run reads as a comet trail instead of a stack printed in place.
        // Counted over a short window, otherwise a long flight would fling a later
        // cue far above the head.
        int trail = 0;
        for (int i = 0; i < _floaters.Count; i++) if (_floaters[i].T < 0.5) trail++;
        if (trail > 3) trail = 3;
        fl.Y = _headY - (int)Math.Round(trail * _floaterStep);
        fl.Jitter = 7 * _scale;
        _floaters.Add(fl);
        if (_floaters.Count > 20) _floaters.RemoveAt(0);

        PlayHitSound();          // every pop plays, even on top of the last one
        _dirty = true;
    }

    void MakeTick(double amount) { MakeTick(amount, false); }

    // Every damage number plays the cue on its own MCI alias, so a new hit never
    // cuts off the previous one.
    void PlayHitSound() {
        // THE VOLUME SLIDER HAS TO BE CONSULTED, and this is the one place that forgot.
        //
        // It checked only the global switch, so dragging the damage slider to 0 % left the hit
        // sound playing at whatever level the alias was last given - and because SetCueVolume
        // pushes the level to the pool as it is dragged, "the last level given" is the value
        // before the final drag to 0. The user's report was exactly that: "set it to 0 % and it
        // does not mute, it comes back at what is effectively 50 %".
        //
        // Routing through PlayCue gives this cue the same rule the other three already had:
        // 0 % is silent, and the switch is the only mute.
        if (_sound == null) return;
        int before = _sound.Plays;
        PlayCue(CUE_HIT, _sound);
        // A pool that could not play is worth recording ONCE - the old code logged on every
        // failed play and then switched sound off to stop the log filling up.
        if (_sound.Plays == before && !_sound.Failed) return;      // nothing was asked for
        if (_sound.Plays == before && _sound.Failed) {
            Log("sound: nothing played (failed=" + _sound.Failed + " err=" + _sound.Error + ")");
            _soundEnabled = false;                       // do not spam the log
        }
    }

    // ------------------------------------------------------------- polling ---
    //
    // Two transports: .NET HttpClient first, then the local Node runtime. Some
    // locked-down Windows setups make schannel refuse to acquire TLS credentials
    // for .NET while Node ships its own OpenSSL stack and still works.

    static readonly HttpClient Http = CreateClient();
    static HttpClient CreateClient() {
        try { ServicePointManager.SecurityProtocol |= SecurityProtocolType.Tls12; } catch { }
        HttpClient c = new HttpClient();
        c.Timeout = TimeSpan.FromSeconds(15);
        return c;
    }

    static string _nodePath;
    static bool _nodeSearched;
    static string FindNode() {
        if (_nodeSearched) return _nodePath;
        _nodeSearched = true;

        string explicitPath = Environment.GetEnvironmentVariable("DSHPET_NODE");
        if (!string.IsNullOrEmpty(explicitPath) && File.Exists(explicitPath)) { _nodePath = explicitPath; return _nodePath; }

        string fromPath = Environment.GetEnvironmentVariable("PATH");
        if (!string.IsNullOrEmpty(fromPath)) {
            foreach (string dir in fromPath.Split(';')) {
                if (dir.Trim().Length == 0) continue;
                try {
                    string cand = Path.Combine(dir.Trim(), "node.exe");
                    if (File.Exists(cand)) { _nodePath = cand; return _nodePath; }
                } catch { }
            }
        }
        string[] roots = new string[] {
            Environment.GetEnvironmentVariable("ProgramFiles"),
            Environment.GetEnvironmentVariable("ProgramFiles(x86)"),
            Environment.GetEnvironmentVariable("ProgramW6432"),
            Environment.GetEnvironmentVariable("LOCALAPPDATA"),
            Environment.GetEnvironmentVariable("APPDATA")
        };
        foreach (string r in roots) {
            if (string.IsNullOrEmpty(r)) continue;
            try {
                foreach (string sub in new string[] { "nodejs\\node.exe", "Programs\\nodejs\\node.exe",
                                                      "nvm\\current\\node.exe" }) {
                    string cand = Path.Combine(r, sub);
                    if (File.Exists(cand)) { _nodePath = cand; return _nodePath; }
                }
                if (Directory.Exists(r)) {
                    foreach (string d in Directory.GetDirectories(r, "node-v*")) {
                        string cand = Path.Combine(d, "node.exe");
                        if (File.Exists(cand)) { _nodePath = cand; return _nodePath; }
                    }
                }
            } catch { }
        }
        return _nodePath;
    }

    string FetchBalance() {
        try {
            return FetchWithHttp();
        } catch (Exception ex) {
            Log("http transport failed (" + ex.GetType().Name + ": " + ex.Message + "), trying node");
        }
        return FetchWithNode();
    }

    string FetchWithHttp() {
        HttpRequestMessage req = new HttpRequestMessage(HttpMethod.Get, _apiUrl);
        req.Headers.TryAddWithoutValidation("Authorization", "Bearer " + _apiKey);
        req.Headers.TryAddWithoutValidation("Accept", "application/json");
        HttpResponseMessage resp = Http.SendAsync(req).GetAwaiter().GetResult();
        // The tariff readout needs cloud time, and this header is the authoritative clock available to
        // us: it is stamped by the server, so it does not care what the machine's clock says.
        try {
            if (resp.Headers.Date.HasValue) {
                _cloudStamp = resp.Headers.Date.Value.UtcDateTime;
                _cloudLocalStamp = DateTime.UtcNow;
                _haveCloudTime = true;
            }
        } catch { }
        string body = resp.Content.ReadAsStringAsync().GetAwaiter().GetResult();
        if (!resp.IsSuccessStatusCode) throw new Exception("HTTP " + (int)resp.StatusCode);
        return body;
    }

    string FetchWithNode() {
        string node = FindNode();
        if (node == null) throw new Exception("node not found");
        string script =
            "const h=require('https');const u=process.env.DSHPET_URL;" +
            "const r=h.get(u,{headers:{Authorization:'Bearer '+process.env.DSHPET_KEY,Accept:'application/json'}}," +
            "s=>{let b='';s.on('data',c=>b+=c);s.on('end',()=>{process.stdout.write(b)})});" +
            "r.on('error',e=>{console.error(String(e.message||e));process.exit(2)});" +
            "r.setTimeout(15000,()=>{console.error('timeout');process.exit(3)});";

        ProcessStartInfo psi = new ProcessStartInfo();
        psi.FileName = node;
        psi.Arguments = "-e \"" + script.Replace("\"", "\\\"") + "\"";
        psi.UseShellExecute = false;
        psi.CreateNoWindow = true;
        psi.RedirectStandardOutput = true;
        psi.RedirectStandardError = true;
        psi.EnvironmentVariables["DSHPET_URL"] = _apiUrl;
        psi.EnvironmentVariables["DSHPET_KEY"] = _apiKey;
        using (Process p = Process.Start(psi)) {
            string outp = p.StandardOutput.ReadToEnd();
            string errp = p.StandardError.ReadToEnd();
            if (!p.WaitForExit(20000)) { try { p.Kill(); } catch { } throw new Exception("node timeout"); }
            if (p.ExitCode != 0 || outp.Trim().Length == 0)
                throw new Exception("node exit " + p.ExitCode + " " + Trunc(errp));
            if (outp.IndexOf("is_available") < 0) throw new Exception("node: " + Trunc(outp));
            return outp;
        }
    }

    static string Trunc(string s) {
        if (s == null) return "";
        s = s.Replace("\r", " ").Replace("\n", " ");
        return s.Length > 200 ? s.Substring(0, 200) : s;
    }

    // snap = the user asked for it (the menu's "refresh now", or --shot): the
    // tablet jumps straight to the value just read. snap = false is the
    // background poll, which keeps walking down in whole steps so every step
    // still gets its hurt animation. Synchronous either way, so a menu click is
    // answered on the spot and always logged.
    // The fetch runs on a worker thread and the result is banked for the next
    // frame: with the poll now every couple of seconds, doing the HTTP call on
    // the UI thread would visibly freeze the widget. The banked reading is
    // applied by OnTick, so the tablet still reacts within one frame of it
    // arriving. Only one request is ever in flight.
    void PollNow(bool snap) {
        if (string.IsNullOrEmpty(_apiKey)) {
            _connected = false;
            _status = S_NOKEY;
            _lastPollResult = "no api key";
            _dirty = true;
            Log("poll skipped: no api key (menu: " + S_SETKEY + ")");
            return;
        }
        if (Interlocked.CompareExchange(ref _pollInFlight, 1, 0) != 0) return;
        bool wantSnap = snap;
        ThreadPool.QueueUserWorkItem(delegate {
            try {
                string body = FetchBalance();
                double bal = ParseCny(body);
                if (double.IsNaN(bal)) { Fail("cannot parse response: " + Trunc(body)); return; }
                lock (_hits) { _bankedBal = bal; _bankedSnap = wantSnap; _bankedValid = true; }
            } catch (Exception ex) {
                Fail(ex.Message);
            } finally {
                Interlocked.Exchange(ref _pollInFlight, 0);
            }
        });
    }

    // applies a banked reading; called from the render tick
    void DrainBankedBalance() {
        // Offline self-tests must ignore even a reading that was already
        // fetched: a request issued during start-up can land in the middle of a
        // simulated sequence and wipe the pending amount, which made the test
        // (and this bug hunt) lie.
        if (_noNetwork) { lock (_hits) { _bankedValid = false; } return; }
        double bal; bool snap;
        lock (_hits) {
            if (!_bankedValid) return;
            bal = _bankedBal; snap = _bankedSnap; _bankedValid = false;
        }
        ApplyBalance(bal, snap);
        Log("poll ok" + (snap ? " (snap)" : "") +
            ": balance=" + bal.ToString("0.00", CultureInfo.InvariantCulture) +
            " printed=" + DrawnText +
            " bookedAt=" + (double.IsNaN(_bookedAt) ? -1 : _bookedAt) +
            " pending=" + _pending.ToString("0.####", CultureInfo.InvariantCulture));
    }

    // blocking variant, used by the offline self-tests only
    void PollNowSync(bool snap) {
        try {
            string body = FetchBalance();
            double bal = ParseCny(body);
            if (double.IsNaN(bal)) { Fail("cannot parse response: " + Trunc(body)); return; }
            ApplyBalance(bal, snap);
        } catch (Exception ex) { Fail(ex.Message); }
    }

    // The whole balance bookkeeping lives here. Nothing else may move the printed
    // number: the total still owed is always re-derived from
    // (_bookedAt - bal), so a reading that arrives at any moment can never make
    // the display drift on its own.
    void ApplyBalance(double bal, bool snap) {
        lock (_hits) {
            _connected = true;
            _lastPollResult = "";
            bool firstReading = double.IsNaN(_realBal);
            double prevReal = _realBal;
            // A poll that brings the figure back down to where the rehearsal started
            // is that rehearsal being undone, NOT money being spent. It has to be
            // recognised before any of the accounting below sees it.
            bool testRollback = !firstReading && !snap && _testBumpAmount > 0 &&
                                bal < prevReal - 1e-6 && bal <= _testBumpFrom + 1e-6;
            _realBal = bal;
            // Today's spend is the balance going DOWN. A rehearsal being rolled back also moves the
            // balance down, but no money was spent, so it is excluded by name rather than by heuristic.
            if (!testRollback) NoteBalanceForSpend(bal);
            bool topUp = false;
            if (firstReading) {
                _bookedAt = bal;
                _bookedBal = bal;
                _pending = 0;
            } else if (snap) {
                // "refresh now" is an explicit resync: believe the server exactly,
                // drop rehearsals, queued debt AND any uncollected top-up. It must
                // not go through the top-up path - a scenario that re-reads the
                // same balance would otherwise book a phantom cent every time.
                _bookedAt = bal;
                _bookedBal = bal;
                _creditPending = 0;
                _testOffset = 0;
                _pending = 0;
                _pendingStep = 0;
                _dueGap = 0;
                // "refresh now" also ends any rehearsal whose fake money has not been
                // rolled back yet - the books are being re-synced to the server.
                if (_testBumpAmount > 0) {
                    _testBumpAmount = 0;
                    _testBumpFrom = double.NaN;
                    DropPhantomBowls();
                }
            } else if (testRollback) {
                // The rehearsal's fake money is gone: the server never had it.
                //
                // What must NOT happen here is what used to happen - the poll being
                // read as spending, so the tablet drained a cent every 0.2s until the
                // whole rehearsal had been eaten while its bowl sat there unclaimed.
                //
                // The uncollected credit and the bowl are deliberately KEPT. That is
                // the whole point of the rehearsal: the bowl stays on screen, feeding
                // it still pays out, and not feeding it costs nothing.
                //
                // The one case that cannot be preserved is a bowl that was ALREADY fed
                // while the fake money was in play: that money is inside the printed
                // number now, and the server gives nothing back, so the readout is
                // re-anchored onto the real balance rather than showing money the
                // account does not have.
                bool collected = _creditPending < _testBumpAmount - 1e-6;
                // Anchor on the TRUE balance. Anchoring on (bal + credit) instead - the
                // obvious-looking choice - put the fake money straight back into the
                // books: the next poll then computed owed = (36+3) - 36 + 3 = 6, capped
                // it to one poll's worth and kept re-deriving it, which is exactly the
                // "it starts draining after two seconds" the user saw.
                _bookedAt = bal;
                // ...but the bowl is still worth collecting, and collecting it adds
                // money the server does not have. While that flag is set, the debt
                // formula leaves the rehearsal's amount out so the payout is not
                // immediately clawed back.
                _testRollbackPending = !collected;
                Log("test top-up rolled back by a real poll: real=" +
                    bal.ToString("0.00", CultureInfo.InvariantCulture) +
                    " collected=" + collected +
                    " pendingBefore=" + _pending.ToString("0.00", CultureInfo.InvariantCulture) +
                    " creditBefore=" + _creditPending.ToString("0.00", CultureInfo.InvariantCulture));
                if (collected) {
                    _bookedAt = bal;
                    _bookedBal = bal;
                    _creditPending = 0;
                    DropPhantomBowls();
                }
                // Either way the phantom debt goes: nothing was spent.
                _pending = 0;
                _pendingStep = 0;
                _dueGap = 0;
                _testBumpAmount = 0;
                _testBumpFrom = double.NaN;
                topUp = true;                 // ...and never a fresh debt
            } else if (bal > prevReal + 1e-6) {
                // ------------------------------------------------------ top-up --
                // The server balance went UP. This is money being added, not a
                // correction, so the readout must NOT follow it: the difference
                // goes into _creditPending and is only collected when the player
                // drags the bowl of rice onto the girl. Until then the printed
                // number stays exactly where it was.
                _bookedBal = double.IsNaN(_bookedBal) ? bal : _bookedBal;   // freeze
                StartCredit(Math.Round(bal - prevReal, 4));
                // Remember whether this bump came from the rehearsal, so the poll that
                // takes it away again can be told apart from real spending.
                if (_inTestTopUp) {
                    _testBumpAmount = Math.Round(bal - prevReal, 4);
                    _testBumpFrom = prevReal;
                }
                topUp = true;
            } else if (bal < prevReal - 1e-6 && _creditPending > StepYuan * 0.5) {
                // The server figure moved DOWN while a top-up is uncollected.
                //
                // Whether that means spending depends on where the NEW figure sits
                // relative to the readout:
                //   new >= printed : the money is still on the server (a rehearsal
                //                    whose local bump was undone by a real poll, or a
                //                    partial spend). Keep/re-derive what is owed.
                //   new <  printed : the money was really spent, so shrink the debt.
                // Comparing the readout against the new figure instead - what this
                // used to do - booked the rehearsal rollback as spending and emptied
                // the bowl, so a delivered bowl credited nothing.
                if (bal >= _bookedBal - 1e-6) {
                    // The new figure is still at or above the readout, so the money is
                    // still on the server: the top-up stands and what is owed is
                    // unchanged. Do NOT re-derive it from (bal - _bookedBal) - that is
                    // 0 here, and overwriting with 0 is exactly what emptied the bowl
                    // (the rehearsal's local bump being undone by a real poll).
                } else {
                    double drop = Math.Round(_bookedBal - bal, 4);
                    _creditPending = Math.Round(_creditPending - drop, 4);
                    if (_creditPending < 0) _creditPending = 0;
                    Log("spend while top-up pending: -" +
                        drop.ToString("0.00", CultureInfo.InvariantCulture) +
                        " left=" + _creditPending.ToString("0.00", CultureInfo.InvariantCulture));
                }
                topUp = true;                 // do not treat this as a fresh debt
            }
            if (DiagBalance) {
                Log("BALDIAG prevReal=" + prevReal.ToString("0.0000") +
                    " bal=" + bal.ToString("0.0000") +
                    " bookedBal=" + _bookedBal.ToString("0.0000") +
                    " pending=" + _creditPending.ToString("0.0000") +
                    " topUp=" + topUp + " snap=" + snap + " first=" + firstReading);
            }
            // A top-up must skip the debt block entirely: it would compute a
            // NEGATIVE owed (-5.00), and the "correction" branch below would then
            // re-anchor the readout straight onto the new balance, defeating the
            // whole point of the bowl.
            if (!firstReading && !snap && !topUp) {
                // The whole difference becomes the debt. A cue already committed
                // but not yet charged counts as part of it, so it is subtracted
                // rather than overwritten - overwriting it is what used to make
                // the number move by less than one animation.
                //
                // _creditPending is ADDED BACK: that money is already inside `bal`
                // (it was a real recharge to the server), it has simply not been
                // collected yet, so it is not a debt. Leaving it out made the debt
                // negative on the poll AFTER a recharge - the balance stops moving
                // once the money lands, so that poll is an ordinary one and took this
                // branch - and the "correction" below then re-anchored the readout
                // onto the live balance. The number climbed on its own a few seconds
                // after a recharge, and delivering the bowl pushed it ABOVE the real
                // balance (user-reported after a real 20 yuan recharge).
                double owed = Math.Round(_bookedAt - bal + _creditPending, 4);
                // A rehearsal that a real poll has already rolled back keeps its bowl
                // collectable, but the money for it is NOT in the server figure: it must
                // not be re-booked as debt on every poll.
                if (_testRollbackPending) {
                    owed = Math.Round(owed - _creditPending, 4);
                    if (owed < 0) owed = 0;
                }
                if (DiagBalance) {
                    Log("DEBTDEBUG bookedAt=" + _bookedAt.ToString("0.0000") +
                        " bookedBal=" + _bookedBal.ToString("0.0000") +
                        " bal=" + bal.ToString("0.0000") +
                        " creditPending=" + _creditPending.ToString("0.0000") +
                        " pendingStep=" + _pendingStep.ToString("0.0000") +
                        " dueGap=" + _dueGap.ToString("0.000") +
                        " rawOwed=" + owed.ToString("0.0000"));
                }
                if (owed < -1e-9) {
                    // the server really is above (booked + uncollected): a recharge that
                    // was never noticed, or a correction. Re-anchor so the debt is only
                    // what is uncharged, and drop the uncollected top-up with it - the
                    // readout now contains that money, so paying the bowl out on top of
                    // it would overshoot.
                    owed = _pending;
                    _bookedAt = Math.Round(bal + owed, 4);
                    _bookedBal = Math.Round(bal + owed, 4);
                    _creditPending = 0;
                }
                if (owed >= _pendingStep - 1e-9) owed = Math.Round(owed - _pendingStep, 4);
                else owed = 0;                    // the cue in flight already covers it
                // one cue is one cent, so cap the queue to keep a huge jump from
                // turning into minutes of animation
                double cap = StepYuan * MaxCuesPerPoll;
                if (owed > cap) owed = cap;
                _pending = owed < 1e-9 ? 0 : owed;
                if (_pending > 1e-9 && _dueGap <= 0) _dueGap = 0;   // first cue now
            }
        }
        _dirty = true;
    }

    void Fail(string why) {
        lock (_hits) { _connected = false; _status = S_LOADING; _lastPollResult = why; }
        Log("poll FAILED: " + why);
        _dirty = true;
    }

    static double ParseCny(string json) {
        int i = json.IndexOf("\"balance_infos\"");
        string scope = i >= 0 ? json.Substring(i) : json;
        int c = scope.IndexOf("\"CNY\"");
        if (c < 0) return double.NaN;
        int j = scope.IndexOf("total_balance", c);
        if (j < 0) return double.NaN;
        int col = scope.IndexOf(':', j);
        if (col < 0) return double.NaN;
        int q1 = scope.IndexOf('"', col + 1);
        if (q1 < 0) return double.NaN;
        int q2 = scope.IndexOf('"', q1 + 1);
        if (q2 < 0) return double.NaN;
        double v;
        if (double.TryParse(scope.Substring(q1 + 1, q2 - q1 - 1), NumberStyles.Float,
                            CultureInfo.InvariantCulture, out v)) return v;
        return double.NaN;
    }

    void Log(string msg) {
        try {
            File.AppendAllText(Path.Combine(_baseDir, "pet.log"),
                DateTime.Now.ToString("s") + " " + msg + "\r\n");
        } catch { }
    }

    // The holiday helpers run on a background thread and are static, so they
    // cannot use the instance Log(); this one writes to the same pet.log through
    // the static base directory.
    static void LogHoliday(string msg) {
        try {
            File.AppendAllText(Path.Combine(AppBaseDir, "pet.log"),
                DateTime.Now.ToString("s") + " " + msg + "\r\n");
        } catch { }
    }

    // ---------------------------------------------------------------- entry --

    [STAThread]
    public static void Run(string baseDir, string[] args) {
        // Anything thrown anywhere below is printed with a stack trace before it
        // leaves: the PowerShell host only reports "Exception calling Run", which
        // says nothing about where it came from. error.log gets the full text too.
        try {
            RunInner(baseDir, args);
        } catch (Exception ex) {
            Console.WriteLine("FATAL: " + ex);
            throw;
        }
    }

    [STAThread]
    static void RunInner(string baseDir, string[] args) {
        try { Native.SetProcessDpiAwarenessContext(new IntPtr(-4)); }
        catch { try { Native.SetProcessDPIAware(); } catch { } }

        bool selftest = Array.IndexOf(args, "--selftest") >= 0;
        bool shot = Array.IndexOf(args, "--shot") >= 0;
        bool menuShot = Array.IndexOf(args, "--menushot") >= 0;
        bool iconShot = Array.IndexOf(args, "--iconshot") >= 0;
        bool topupTest = Array.IndexOf(args, "--topup") >= 0;
        bool simchain = Array.IndexOf(args, "--simchain") >= 0;
        bool perfTest = Array.IndexOf(args, "--perf") >= 0;
        bool perfScale = Array.IndexOf(args, "--perfscale") >= 0;
        bool ulwTest = Array.IndexOf(args, "--ulwcheck") >= 0;
        bool animTail = Array.IndexOf(args, "--animtail") >= 0;
        bool bowlGirl = Array.IndexOf(args, "--bowlgirl") >= 0;
        bool ironBump = Array.IndexOf(args, "--ironbump") >= 0;
        bool panelCheck = Array.IndexOf(args, "--panelcheck") >= 0;
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);

        DshPet pet = new DshPet(baseDir, args);
        // Any --flag makes this a diagnostic process: see the guard in SaveState.
        for (int ai = 0; ai < args.Length; ai++)
            if (args[ai].StartsWith("--")) { pet.MarkDiagnosticRun(); break; }
        if (selftest || shot || menuShot || iconShot || topupTest || simchain || perfTest || ulwTest ||
            animTail || bowlGirl || panelCheck || perfScale || ironBump) pet.NoSaveForTest();

        if (shot) {
            System.Windows.Forms.Timer shotTimer = new System.Windows.Forms.Timer();
            shotTimer.Interval = 2500;
            shotTimer.Tick += delegate {
              // Wrapped: a GDI+ failure here otherwise shows up only as a
              // modal "Parameter is not valid" box, which names no line.
              try {
                shotTimer.Stop();
                pet.PollNowSyncPublic(false);
                Console.WriteLine("rest  : " + pet.ShakeReport());

                // menu "refresh now" must print the latest value immediately
                Console.WriteLine("shown after auto poll     = " + pet.DrawnText);
                pet.PollNowSyncPublic(true);
                Console.WriteLine("shown after refresh now   = " + pet.DrawnText +
                                  "   (must equal the live balance)");

                // regression: the number must keep stepping for EVERY rehearsal.
                // It used to freeze after ten because the offset was capped.
                pet.PollNowSyncPublic(true);
                string before = pet.DrawnText;
                for (int i = 1; i <= 15; i++) pet.MakeTick(0.03, true);
                Console.WriteLine("printed before 15 cues    = " + before);
                Console.WriteLine("printed after 15 cues     = " + pet.DrawnText +
                                  "   (must be 0.45 lower, not frozen)");

                // and a rehearsal must not survive a refresh as phantom spend
                for (int i = 1; i <= 3; i++) pet.MakeTick(pet.StepValue, true);
                Console.WriteLine("shown after 3 test cues   = " + pet.DrawnText);
                pet.PollNowSyncPublic(true);
                Console.WriteLine("shown after refresh again = " + pet.DrawnText +
                                  "   <- back to the live balance, no drift");

                // visual check of a fast run: five cues at the real 0.2s rhythm,
                // captured mid-cascade so the trail spacing can be inspected
                pet.ResetDemoForTest();
                pet.PollNowSyncPublic(true);
                pet.DemoCharge(0.05);
                pet.PumpTicks(6);                    // first cue lands
                pet.PumpTicks(6);                    // second, 0.2s later
                pet.PumpTicks(6);                    // third
                pet.SaveCanvas(Path.Combine(baseDir, "_shot_cascade.png"));
                Console.WriteLine("cascade: " + pet.ShakeReport() +
                                  "  floaters=" + pet.FloaterCountPublic +
                                  "  printed=" + pet.DrawnText);
                pet.PumpTicks(360);                  // let the run finish
                Console.WriteLine("cascade settled -> printed " + pet.DrawnText);

                pet.ResetDemoForTest();
                pet.MakeTick(pet.StepValue, true);   // rehearsal for the screenshot
                pet.BurnFrames(2);
                Console.WriteLine("shake1: " + pet.ShakeReport());
                pet.SaveCanvas(Path.Combine(baseDir, "_shot_flash.png"));
                pet.BurnFrames(3);
                Console.WriteLine("shake2: " + pet.ShakeReport());
                pet.BurnFrames(9);
                Console.WriteLine("after : " + pet.ShakeReport());
                pet.SaveCanvas(Path.Combine(baseDir, "shot.png"));
                Console.WriteLine("shot ok: connected=" + pet._connected +
                                  " drawn=" + pet.DrawnText);

                // Top-up visual: drop a bowl without touching the network, let it
                // fall, and capture it so the artwork and its landing can be
                // checked by eye. Also proves the bowl does not disturb the
                // printed number.
                string riceBefore = pet.DrawnText;
                pet.StartCreditPublic(5.00);
                pet.PumpTicks(10);                   // let it start falling
                pet.SaveCanvas(Path.Combine(baseDir, "_shot_rice.png"));
                Console.WriteLine("rice: printed=" + pet.DrawnText +
                                  " (must equal " + riceBefore + ")" +
                                  "  bowl=" + pet.RiceReport());
                // The bowl is its own window now, so SaveCanvas (this window's
                // canvas) cannot show it. Grab the whole desktop instead, which is
                // the only honest way to check WHERE it falls.
                pet.CaptureDesktop(Path.Combine(baseDir, "_shot_desktop.png"));
                Console.WriteLine("geom: " + pet.GeomReport());
                Console.WriteLine("hitmap: " + pet.HitMapReport());
                // Interaction gates: the bowl must be pickable, and the menu must
                // fire on the girl but NOT on the bowl. Both broke silently before.
                {
                    Rice rr = pet.RiceState;
                    if (rr != null) {
                        // Bowl coords are SCREEN and the window origin is the screen
                        // origin, so they are directly comparable to the hit map.
                        int bx = (int)Math.Round(rr.X), by = (int)Math.Round(rr.Y);
                        Console.WriteLine("gates: bowlHitOnBowl=" + pet.BowlHitPublic(bx, by) +
                                          " (want True)  girlSolidOnBowl=" + pet.GirlSolidPublic(bx, by) +
                                          " (want False -> menu must NOT open on the bowl)");
                    }
                    int gx, gy;
                    if (pet.GirlSample(out gx, out gy)) {
                        Console.WriteLine("gates: girlSolidOnGirl=" + pet.GirlSolidPublic(gx, gy) +
                                          " (want True -> menu opens here)  at " + gx + "," + gy +
                                          "  bowlHitOnGirl=" + pet.BowlHitPublic(gx, gy));
                    } else Console.WriteLine("gates: FAIL - no solid girl pixel in the hit map");
                }
                pet.DumpCanvasScaled(Path.Combine(baseDir, "_shot_canvas.png"));
                pet.PumpTicks(60);                   // let it settle
                Console.WriteLine("rice settled: " + pet.RiceReport());
                pet.CaptureDesktop(Path.Combine(baseDir, "_shot_desktop2.png"));
                Console.WriteLine("geom: " + pet.GeomReport());
                Console.WriteLine("rice after settle: " + pet.RiceReport() +
                                  "   bowlBottomOnScreen=" + pet.BowlBottomOnScreen());

                // Deliver it and catch the hearts mid-flight, plus the green "+x.xx"
                // credit number that lands at the same moment.
                pet.FeedRiceForShot();
                pet.PumpTicks(6);
                pet.SaveCanvas(Path.Combine(baseDir, "_shot_hearts.png"));
                Console.WriteLine("hearts: printed=" + pet.DrawnText +
                                  "  bowl=" + pet.RiceReport() +
                                  "  hearts=" + pet.HeartsPublic);
                Application.Exit();
              } catch (Exception ex) {
                Console.WriteLine("SHOT CRASH: " + ex.GetType().FullName);
                Console.WriteLine(ex.ToString());
                Console.Out.Flush();
                Application.Exit();
              }
            };
            shotTimer.Start();
            Application.Run(pet);
            return;
        }

        if (Array.IndexOf(args, "--iconshot") >= 0) {
            // Icon sheet: every menu icon at 1x and blown up 8x with no
            // resampling, so the artwork itself can be judged and any shape that
            // runs off its 16x16 cell is obvious.
            int[] kinds = new int[] { IC_REFRESH, IC_BOLT, IC_BOWL, IC_CASCADE, IC_SIZE,
                                      IC_SOUND, IC_KEY, IC_QUIT, IC_MUTE, IC_THEME };
            int s = 8, cell = 16, pad = 6;
            int cw = cell * s + pad;
            using (Bitmap sheet = new Bitmap(kinds.Length * cw + pad, cw + cell + pad * 3,
                                             PixelFormat.Format32bppArgb)) {
                using (Graphics g = Graphics.FromImage(sheet)) {
                    g.Clear(Color.White);
                    g.InterpolationMode = InterpolationMode.NearestNeighbor;
                    g.PixelOffsetMode = PixelOffsetMode.Half;
                    for (int i = 0; i < kinds.Length; i++) {
                        using (Bitmap ic = pet.MakeIcon(kinds[i])) {
                            int x = pad + i * cw;
                            g.DrawRectangle(Pens.Silver, x, pad, cw - 1, cw - 1);
                            g.DrawImage(ic, new Rectangle(x, pad, cell * s, cell * s));
                            g.DrawImage(ic, new Rectangle(x + (cell * s - cell) / 2, pad + cw + 2, cell, cell));
                        }
                    }
                }
                sheet.Save(Path.Combine(baseDir, "_icon_sheet.png"), ImageFormat.Png);
            }
            Console.WriteLine("icon sheet -> _icon_sheet.png (" + kinds.Length + " icons, 1x and " + s + "x)");
            return;
        }

        // Panel / number layout: how the readout fits the tablet at any digit count.
        if (Array.IndexOf(args, "--panelcheck") >= 0) {
            pet.PanelCheckReport();
            return;
        }

        if (selftest) {
            Console.WriteLine("diag: " + pet.Diag());
            pet.GoOffline();                  // deterministic: no background poll
            pet.RunSelfTest(baseDir);
            Application.Exit();
            return;
        }

        // Frame-budget breakdown (development flag, offline, no window shown but the
        // real handle exists so PushLayer is included).
        if (Array.IndexOf(args, "--perf") >= 0 || Array.IndexOf(args, "--perfscale") >= 0 ||
            Array.IndexOf(args, "--ulwcheck") >= 0 || Array.IndexOf(args, "--ironbump") >= 0 ||
            Array.IndexOf(args, "--animtail") >= 0 || Array.IndexOf(args, "--bowlgirl") >= 0) {
            bool ulw = Array.IndexOf(args, "--ulwcheck") >= 0;
            bool perfScaleRun = Array.IndexOf(args, "--perfscale") >= 0;
            bool ironBumpRun = Array.IndexOf(args, "--ironbump") >= 0;
            System.Windows.Forms.Timer pf = new System.Windows.Forms.Timer();
            pf.Interval = 400;
            pf.Tick += delegate {
                pf.Stop();
                try {
                    if (ulw) { Console.WriteLine("layered-window push self-check"); pet.UlwCheckReport(); }
                    else if (Array.IndexOf(args, "--animtail") >= 0) pet.RunAnimationTailTest();
                    else if (Array.IndexOf(args, "--bowlgirl") >= 0) pet.RunBowlOverGirlTest();
                    else if (ironBumpRun) pet.RunIronPotBumpTest();
                    else if (perfScaleRun) pet.PerfScaleReport();
                    else pet.PerfReport();
                } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            pf.Start();
            Application.Run(pet);
            return;
        }

        // Audio engine check: decode the four shipped cues with Media Foundation,
        // confirm the durations match what MCI reports, then run a trim+gain round
        // trip through the wav writer and read it back. This is the part of the
        // custom-sound feature that cannot be verified by inspection - it either
        // decodes real samples or it does not.
        if (Array.IndexOf(args, "--audiocheck") >= 0) {
            pet.GoOffline();
            pet.NoSaveForTest();
            System.Windows.Forms.Timer at = new System.Windows.Forms.Timer();
            at.Interval = 300;
            at.Tick += delegate {
                at.Stop();
                try { pet.RunAudioEngineTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            at.Start();
            Application.Run(pet);
            return;
        }

        // Legacy clip migration: only runs on a machine that has an old-format sidecar, so
        // without this it would be dead code until a real user upgraded.
        if (Array.IndexOf(args, "--librarymigrate") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer mt2 = new System.Windows.Forms.Timer();
            mt2.Interval = 300;
            mt2.Tick += delegate {
                mt2.Stop();
                try { pet.RunLibraryMigrationTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            mt2.Start();
            Application.Run(pet);
            return;
        }

        // Per-cue volume check: four independent levels, each reaching its own pool.
        if (Array.IndexOf(args, "--cuevolume") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer vt = new System.Windows.Forms.Timer();
            vt.Interval = 300;
            vt.Tick += delegate {
                vt.Stop();
                try { pet.RunCueVolumeTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            vt.Start();
            Application.Run(pet);
            return;
        }

        // Audio editor shot: opens the trim/gain window on a real cue and captures it, so
        // the dialog's look can be checked without a human driving the file picker.
        if (Array.IndexOf(args, "--editshot") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer et = new System.Windows.Forms.Timer();
            et.Interval = 600;
            et.Tick += delegate {
                et.Stop();
                try { pet.ShowEditorShot(baseDir); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Application.Exit();
            };
            et.Start();
            Application.Run(pet);
            return;
        }

        // Custom sound effect check: write a trimmed clip as a cue's replacement, confirm the
        // pool opens THAT file, then reset. No dialog - everything behind it.
        if (Array.IndexOf(args, "--customeffect") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer xt = new System.Windows.Forms.Timer();
            xt.Interval = 300;
            xt.Tick += delegate {
                xt.Stop();
                try { pet.RunCustomEffectTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            xt.Start();
            Application.Run(pet);
            return;
        }

        // Menu structure check: prints the tree and asserts it against the structure the
        // user specified. Text, not a screenshot - see MenuTreeReport for why.
        if (Array.IndexOf(args, "--menucheck") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer ct = new System.Windows.Forms.Timer();
            ct.Interval = 300;
            ct.Tick += delegate {
                ct.Stop();
                try { pet.RunMenuCheckTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            ct.Start();
            Application.Run(pet);
            return;
        }

        // Demo window shot, for the same reason as the settings window: it is only reachable by
        // right-clicking the pet.
        if (Array.IndexOf(args, "--shotdemo") >= 0) {
            pet.NoSaveForTest();
            if (Array.IndexOf(args, "--menudark") >= 0) pet.ApplyThemeForShot(true);
            System.Windows.Forms.Timer dt = new System.Windows.Forms.Timer();
            dt.Interval = 600;
            dt.Tick += delegate {
                dt.Stop();
                try { pet.CaptureDemoWindow(baseDir); }
                catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            dt.Start();
            Application.Run(pet);
            return;
        }

        // Window icons: the four title-bar windows must load the shipped glyphs, not the .NET default
        // form icon. Worth a guard because the default is INVISIBLE in every other test - it is a
        // perfectly valid Icon object, so nothing throws and no screenshot of the client area shows
        // it. The failure looks exactly like success.
        if (Array.IndexOf(args, "--winicons") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer wt = new System.Windows.Forms.Timer();
            wt.Interval = 300;
            wt.Tick += delegate {
                wt.Stop();
                try { pet.RunWindowIconTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            wt.Start();
            Application.Run(pet);
            return;
        }

        // Menu shot: opens the REAL menu and captures it, so what the user sees can be compared with
        // what the code claims. A sheet of MakeIcon output proves the drawing is right; only this
        // proves the menu displays it.
        //
        // --shotmenu already did this, so this flag reuses the same capture path rather than adding a
        // second one: two capture routines would be two things to keep correct.
        if (Array.IndexOf(args, "--menushot") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer ms = new System.Windows.Forms.Timer();
            ms.Interval = 600;
            int mstep = 0;
            ms.Tick += delegate {
                switch (mstep) {
                case 0:
                    // Show in one tick, capture in the next: the popup needs a pass through the
                    // message loop before it has painted.
                    pet.OpenRootMenu(pet.MenuOrigin());
                    break;
                case 1: {
                    Rectangle mcap = pet.MenuBounds();
                    pet.CaptureRegion(Path.Combine(baseDir, "_menu_shot.png"), mcap, 10);
                    Console.WriteLine("menu rect: " + mcap);
                    Console.WriteLine("metrics : " + pet.MenuMetrics());
                    break;
                }
                default:
                    ms.Stop();
                    pet.CloseMenus();
                    Console.WriteLine("done");
                    Application.Exit();
                    break;
                }
                mstep++;
            };
            ms.Start();
            Application.Run(pet);
            return;
        }

        // Icon sheet: renders every menu icon to one magnified PNG, so what the menu actually SHOWS
        // can be looked at directly. Reading the drawing code is not enough - the on-screen icon was
        // reported as a four-square Windows logo while IC_CASCADE is drawn as three green chevrons,
        // and only the rendered pixels can settle which is true.
        if (Array.IndexOf(args, "--iconsheet") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer it2 = new System.Windows.Forms.Timer();
            it2.Interval = 300;
            it2.Tick += delegate {
                it2.Stop();
                try { pet.DumpIconSheet(args); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            it2.Start();
            Application.Run(pet);
            return;
        }

        // Tray icon: it must be the shipped one, not the stock Windows application icon.
        if (Array.IndexOf(args, "--trayicon") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer tt = new System.Windows.Forms.Timer();
            tt.Interval = 300;
            tt.Tick += delegate {
                tt.Stop();
                try { pet.RunTrayIconTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            tt.Start();
            Application.Run(pet);
            return;
        }

        // Click-away dismissal: the menu must close when the user clicks outside it, which the
        // window's own click-through hit test makes non-obvious.
        if (Array.IndexOf(args, "--clickaway") >= 0) {
            pet.NoSaveForTest();
            pet.SetDiagClickAwayForTest();
            System.Windows.Forms.Timer ct = new System.Windows.Forms.Timer();
            ct.Interval = 400;
            ct.Tick += delegate {
                ct.Stop();
                try { pet.RunClickAwayTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            ct.Start();
            Application.Run(pet);
            return;
        }

        // Mute per cue: every trigger path must respect 0 %. Added after the damage cue was found
        // playing at 0 % because its call site checked only the global switch.
        if (Array.IndexOf(args, "--mutecheck") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer mt3 = new System.Windows.Forms.Timer();
            mt3.Interval = 300;
            mt3.Tick += delegate {
                mt3.Stop();
                try { pet.RunMutePerCueTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            mt3.Start();
            Application.Run(pet);
            return;
        }

        // Volume preview: adjusting a level must be silent while the preview button sounds.
        if (Array.IndexOf(args, "--preview") >= 0) {
            pet.NoSaveForTest();
            System.Windows.Forms.Timer pt = new System.Windows.Forms.Timer();
            pt.Interval = 300;
            pt.Tick += delegate {
                pt.Stop();
                try { pet.RunPreviewTest(); } catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            pt.Start();
            Application.Run(pet);
            return;
        }

        // Settings window shots: one per page. The window is otherwise reachable only by
        // right-clicking the pet, so a layout bug in it stays invisible until someone opens it.
        if (Array.IndexOf(args, "--shotwin") >= 0) {
            pet.NoSaveForTest();
            int page = 0;
            bool pageGiven = false;
            for (int i = 0; i < args.Length; i++) {
                if (args[i] == "--page" && i + 1 < args.Length) {
                    int.TryParse(args[i + 1], out page);
                    pageGiven = true;
                }
            }
            if (Array.IndexOf(args, "--menudark") >= 0) pet.ApplyThemeForShot(true);
            System.Windows.Forms.Timer wt = new System.Windows.Forms.Timer();
            wt.Interval = 600;
            wt.Tick += delegate {
                wt.Stop();
                try { pet.CaptureSettingsWindow(baseDir, page, !pageGiven); }
                catch (Exception ex) { Console.WriteLine("diag FAILED: " + ex); }
                Console.WriteLine("done");
                Application.Exit();
            };
            wt.Start();
            Application.Run(pet);
            return;
        }

        // Menu appearance check. A dropdown is its own popup window, so the only
        // honest way to see the beautified menu is to open it for real and grab
        // that part of the screen. It is never part of a release run: --menushot
        // is a development flag, like --shot.
        if (Array.IndexOf(args, "--menushot") >= 0) {
            pet.GoOffline();                  // no network while the menu is open
            // --menudark forces the dark palette for the shot, so both looks can be
            // captured and compared without touching state.ini. (A separate switch
            // rather than --menushot=dark: an '=' argument survives routing through
            // powershell.exe -File badly enough to be unreliable.)
            // Without the flag the shot uses whatever theme state.ini asked for -
            // forcing light here used to override the user's saved choice.
            bool shotDark = Array.IndexOf(args, "--menudark") >= 0;
            if (shotDark) pet.ApplyThemeForShot(true);
            Console.WriteLine("theme: " + (pet.IsDarkThemeForShot ? "dark" : "light"));
            // The menu is five flat rows now, so one shot covers it: there are no submenus left to
            // walk into. The settings window's pages are photographed by --shotwin instead, which
            // opens each page directly rather than navigating a cascade.
            int step = 0;
            System.Windows.Forms.Timer mt = new System.Windows.Forms.Timer();
            mt.Interval = 600;
            mt.Tick += delegate {
                Rectangle cap;
                switch (step) {
                case 0:
                    // Show in one tick, capture in the next: the popup needs a pass through the
                    // message loop before it has actually painted.
                    Console.WriteLine("menu: " + pet.MenuReport());
                    pet.OpenRootMenu(pet.MenuOrigin());
                    break;
                case 1:
                    cap = pet.MenuBounds();
                    pet.CaptureRegion(Path.Combine(baseDir, "_menu_1_root.png"), cap, 10);
                    Console.WriteLine("root menu rect: " + cap);
                    Console.WriteLine("drops: " + pet.DropDownReport());
                    Console.WriteLine("metrics: " + pet.MenuMetrics());
                    break;
                default:
                    mt.Stop();
                    pet.CloseMenus();
                    Console.WriteLine("menu shot done");
                    Application.Exit();
                    break;
                }
                step++;
            };
            mt.Start();
            Application.Run(pet);
            return;
        }

        if (Array.IndexOf(args, "--topup") >= 0) {
            pet.RunTopUpTest();
            Console.WriteLine();
            pet.RunTestTopUp();               // the menu entry, same path
            Console.WriteLine();
            pet.RunMultiBowlTest();           // one bowl per top-up
            Console.WriteLine();
            pet.RunResizeWithBowlTest();      // resize with a bowl out
            Console.WriteLine();
            pet.RunSnapBackTest();            // the girl returns to her corner
            Console.WriteLine();
            pet.RunFeedGraceTest();           // the pause before spending resumes
            Console.WriteLine();
            pet.RunSoundTest();               // the sound submenu really applies
            Console.WriteLine();
            pet.RunAnimationTailTest();       // nothing frozen after an animation ends
            Console.WriteLine();
            pet.RunBowlOverGirlTest();        // a bowl must not erase the girl
            Console.WriteLine();
            pet.RunTopUpHoldTest();           // an uncollected top-up stays frozen
            Console.WriteLine();
            pet.RunInertiaTest();             // a thrown bowl keeps its momentum
            Console.WriteLine();
            pet.RunTestTopUpDebtTest();       // an unclaimed rehearsal is never debt
            Console.WriteLine();
            pet.PanelCheckReport(false);      // every number shape fits the tablet
            Console.WriteLine();
            return;
        }

        // Standalone: expression state machine (charge -> grimace -> back to normal).
        if (Array.IndexOf(args, "--exprcheck") >= 0) {
            pet.NoSaveForTest();
            pet.RunExpressionTest();
            Console.WriteLine("done");
            Application.Exit();
            return;
        }

        // Standalone: render the feeding hearts for inspection.
        if (Array.IndexOf(args, "--hearts") >= 0) {
            pet.RunHeartShotTest(baseDir);
            Console.WriteLine("done");
            Application.Exit();
            return;
        }

        // Standalone: several bowls at once - batch lock.
        if (Array.IndexOf(args, "--multitarget") >= 0) {
            pet.NoSaveForTest();
            pet.RunMultiTargetTest();
            Console.WriteLine("done");
            Application.Exit();
            return;
        }

        // Standalone: the iron pot that lands on her head.
        // Reports the geometry the pet is ACTUALLY running with, read from the real state.ini,
        // without touching anything. Needed to map a pixel measured in a screen recording onto
        // the erase mask: the mask is anchored to the widget, so its screen position depends on
        // _offX/_offY/_w, and guessing those from a video is what kept sending me in circles.
        if (Array.IndexOf(args, "--seam") >= 0) {
            pet.NoSaveForTest();
            pet.SeamCheck();
            Console.WriteLine("done");
            Application.Exit();
            return;
        }

        // Head pat trigger: walks press -> 200 ms hold -> active, through the same methods the app
        // uses, so a failure points at what the app feeds them rather than at the logic.
        if (Array.IndexOf(args, "--peaktick") >= 0) {
            pet.NoSaveForTest();
            pet.RunPeakTickTest();
            Console.WriteLine("done");
            Application.Exit();
            return;
        }

        if (Array.IndexOf(args, "--peakcheck") >= 0) {
            pet.NoSaveForTest();
            pet.RunPeakCheckTest();
            Console.WriteLine("done");
            Application.Exit();
            return;
        }

        if (Array.IndexOf(args, "--fxcheck") >= 0) {
            pet.NoSaveForTest();
            pet.RunFxCheckTest();
            Console.WriteLine("done");
            Application.Exit();
            return;
        }

        if (Array.IndexOf(args, "--pattrigger") >= 0) {
            pet.NoSaveForTest();
            pet.RunPatTriggerTest();
            Console.WriteLine("done");
            Application.Exit();
            return;
        }

        // Interactive solver for the head-pat hand placement.
        //
        // This replaces "edit a constant, rebuild, run --patcheck, look at a dumped frame, guess again".
        // That loop cost about 20 s a round and, worse, the judgement was made from memory: by the time
        // the next frame came back, the previous one was a faded impression. Here the hand is dragged
        // with the mouse and the picture is the FINAL composite, so there is nothing to remember.
        //
        // It exists because the hand placement has four coupled numbers and is judged purely by eye -
        // exactly the case the interactive-tool note describes: mouse-expressible, eye-judged, slow
        // feedback, and the result has to end up as constants in the code.
        // TEMP: render the dialogs to PNG so the styling can be inspected.
        // The breadcrumb panel, root view and demo view, photographed without switching the menu over.
        if (Array.IndexOf(args, "--crumbshot") >= 0) {
            pet.NoSaveForTest();
            try {
                CrumbPanel cp = new CrumbPanel(pet);
                cp.ShowAt(new Point(200, 200), pet);
                System.Threading.Thread.Sleep(300);
                Application.DoEvents();
                pet.CaptureWindowTo(System.IO.Path.Combine(baseDir, "_crumb_root.png"),
                                    cp.Handle, cp.ClientSize.Width, cp.ClientSize.Height);
                Console.WriteLine("  root    : demoView=" + cp.DemoViewForTest +
                                  " size=" + cp.ClientSize.Width + "x" + cp.ClientSize.Height);
                cp.GoDemoForTest();
                System.Threading.Thread.Sleep(250);
                Application.DoEvents();
                pet.CaptureWindowTo(System.IO.Path.Combine(baseDir, "_crumb_demo.png"),
                                    cp.Handle, cp.ClientSize.Width, cp.ClientSize.Height);
                Console.WriteLine("  demo    : demoView=" + cp.DemoViewForTest +
                                  " size=" + cp.ClientSize.Width + "x" + cp.ClientSize.Height);
                bool staged = cp.DemoViewForTest;
                cp.GoRootForTest();
                // The settings host: three pages, each rendering the real page body.
                for (int pg = 0; pg < 3; pg++) {
                    cp.GoSettingsForTest(pg);
                    if (pg == 0) {
                        cp.SettleForTest();
                        Rectangle hr;
                        if (cp.HostSizeRect(3, out hr)) {
                            Point hp = cp.HostToPanel(new Point(hr.X + 60, hr.Y + hr.Height / 2));
                            cp.HoverAtForTest(hp);
                            Console.WriteLine("  hover   : row4 host=" + hr + " panel=" + hp);
                        }
                    }
                    System.Threading.Thread.Sleep(200);
                    Application.DoEvents();
                    pet.CaptureWindowTo(System.IO.Path.Combine(baseDir, "_crumb_set" + pg + ".png"),
                                        cp.Handle, cp.ClientSize.Width, cp.ClientSize.Height);
                    Console.WriteLine("  settings" + pg + " : size=" + cp.ClientSize.Width + "x" +
                                  cp.ClientSize.Height + " page=" + cp.SettingsPageForTest +
                                  " neededW=" + cp.HostNeededWidthForTest());
    
                }
                cp.GoRootForTest();
                bool backOk = !cp.DemoViewForTest;
                cp.GoDemoForTest();
                System.Threading.Thread.Sleep(120);
                cp.GoRootForTest();
                cp.GoSettingsForTest(1);
                System.Threading.Thread.Sleep(120);
                cp.GoRootForTest();
                Console.WriteLine("  inPlace : demo=" + staged + " back=" + backOk + "  " +
                                  ((staged && backOk) ? "ok (content swaps, the panel itself stays)"
                                                      : "MISMATCH (the view did not swap)"));
                // ---- interaction, driven through the panel's own hit list ----
                //
                // Asserted on the EFFECT (the pet's values), not on the call, so a click that
                // silently did nothing cannot pass.
                cp.GoSettingsForTest(1);                  // volume page
                cp.SettleForTest();
                System.Threading.Thread.Sleep(200);
                Application.DoEvents();
                Rectangle track;
                bool haveSlider = cp.HostSliderRect(0, out track);
                int before = pet.CueVolumeUi(0);
                if (haveSlider) {
                    cp.SimulateHostClick(cp.HostToPanel(new Point(track.X + 1, track.Y + track.Height / 2)));
                    Application.DoEvents();
                }
                int atLeft = pet.CueVolumeUi(0);
                if (haveSlider) {
                    cp.SimulateHostClick(cp.HostToPanel(new Point(track.Right - 1, track.Y + track.Height / 2)));
                    Application.DoEvents();
                }
                int atRight = pet.CueVolumeUi(0);
                Console.WriteLine("  dbg     : hits " + cp.DumpHitsForTest());
                Console.WriteLine("  probe   : " + cp.ProbeHitsForTest() +
                                  "   (kinds hit at each recorded rect; 0 = miss)");
                Console.WriteLine("  dbg2    : track=" + track + " origin=" + cp.SetOriginForTest +
                                  " hit=" + cp.HostHitTestForTest(new Point(track.X + 1, track.Y + 12)) +
                                  " hits=" + cp.HostHitCountForTest + " size=" + cp.ClientSize +
                                  " disposed=" + cp.IsDisposed + " page=" + cp.SettingsPageForTest);
                bool sliderWorks = haveSlider && atLeft <= 5 && atRight >= 95 && atLeft != atRight;
                Console.WriteLine("  slider  : before=" + before + "% left=" + atLeft +
                                  "% right=" + atRight + "%  " +
                                  (sliderWorks ? "ok (the panel drives the real control)"
                                               : "MISMATCH (the click did not reach the control)"));
                if (haveSlider) {   // restore the user's level
                    cp.SimulateHostClick(cp.HostToPanel(new Point((track.X + track.Right) / 2, track.Y + track.Height / 2)));
                    Application.DoEvents();
                }

                // Theme segmented control: click the other half and the flag must flip.
                cp.GoSettingsForTest(0);
                cp.SettleForTest();
                System.Threading.Thread.Sleep(200);
                Application.DoEvents();
                Rectangle seg;
                // Click the OTHER option. Clicking the one already selected changes nothing, and the
                // assertion then reads that as "the control does not respond" - which is what it did,
                // twice, before this was spotted.
                bool wantDark = !pet.IsDarkThemeUi;
                bool haveSeg = cp.HostSegmentedRect(wantDark ? 1 : 0, out seg);
                if (haveSeg) {
                    cp.SimulateHostClick(cp.HostToPanel(new Point(seg.X + seg.Width / 2, seg.Y + seg.Height / 2)));
                    Application.DoEvents();
                }
                bool themeWorks = haveSeg && pet.IsDarkThemeUi == wantDark;
                Console.WriteLine("  segment : dark=" + pet.IsDarkThemeUi + " (wanted " + wantDark +
                                  ")  " +
                                  (themeWorks ? "ok (segmented control responds)"
                                              : "MISMATCH (segmented control did not respond)"));
                if (haveSeg) {   // put the user's theme back
                    cp.SimulateHostClick(cp.HostToPanel(new Point(seg.X + seg.Width / 2, seg.Y + seg.Height / 2)));
                    Application.DoEvents();
                }
                Console.WriteLine("  verdict : " + ((sliderWorks && themeWorks)
                    ? "OK - panel renders, swaps in place, grows upward, and drives the real controls"
                    : "FAIL - see slider/segment above"));
                cp.GoRootForTest();
                // Position: the panel must grow UP from the anchor and stay on screen. A click 60 px
                // above the bottom edge is the case that used to overflow.
                Rectangle wa2 = Screen.PrimaryScreen.WorkingArea;
                Point low = new Point(300, wa2.Bottom - 60);
                CrumbPanel cp2 = new CrumbPanel(pet);
                cp2.ShowAt(low, pet);
                System.Threading.Thread.Sleep(200);
                Application.DoEvents();
                int rootBottom = cp2.Bottom, rootTop = cp2.Top;
                cp2.GoDemoForTest();          // gets much taller
                System.Threading.Thread.Sleep(200);
                Application.DoEvents();
                int demoBottom = cp2.Bottom, demoTop = cp2.Top, demoH = cp2.Height;
                bool inside = demoTop >= wa2.Top && demoBottom <= wa2.Bottom;
                bool grewUp = demoTop < rootTop;
                bool bottomHeld = Math.Abs(demoBottom - rootBottom) <= 2;
                Console.WriteLine("  anchor  : y=" + low.Y + " (work bottom " + wa2.Bottom + ")");
                Console.WriteLine("  root    : top=" + rootTop + " bottom=" + rootBottom);
                Console.WriteLine("  demo    : top=" + demoTop + " bottom=" + demoBottom +
                                  " height=" + demoH);
                Console.WriteLine("  position: onScreen=" + inside + " grewUp=" + grewUp +
                                  " bottomHeld=" + bottomHeld + "  " +
                                  ((inside && grewUp && bottomHeld)
                                   ? "ok (grows upward from the click, stays visible)"
                                   : "MISMATCH (overflows or grew downward)"));
   if (haveSlider) {   // restore the user's level
                    cp.SimulateHostClick(cp.HostToPanel(new Point((track.X + track.Right) / 2, track.Y + track.Height / 2)));
                    Application.DoEvents();
                }

                // Theme segmented control: click the other half and the flag must flip.
                cp.GoSettingsForTest(0);
                System.Threading.Thread.Sleep(200);
                Application.DoEvents();
                cp.GoRootForTest();
                cp.Close();
            } catch (Exception ex) { Console.WriteLine("crumbshot failed: " + ex.Message + " @ " + ex.StackTrace); }
            Application.Exit();
            return;
        }

        if (Array.IndexOf(args, "--dialogshot") >= 0) {
            pet.NoSaveForTest();
            try {
                InputDialog d1 = new InputDialog("API Key", "paste your key here", "", "",
                                                 880, true);
                d1.Show();
                // PrintWindow renders on demand, but a window that has only just been shown has not laid out
                // or painted its children yet - the first capture came back with the buttons cut off. The
                // capture was right; the window was not ready. --editshot already waited.
                System.Threading.Thread.Sleep(300);
                Application.DoEvents();
                pet.CaptureWindowTo(System.IO.Path.Combine(baseDir, "_dialog_apiKey.png"),
                                    d1.Handle, d1.ClientSize.Width, d1.ClientSize.Height);
                d1.Close();
                InputDialog d2 = new InputDialog("T", "P", "%", "50");
