        Point G = GirlRefScreen();
        return "bowl=(" + r.X.ToString("0") + "," + r.Y.ToString("0") + ")" +
               " girl=(" + G.X + "," + G.Y + ")" +
               " d=" + BowlDistanceForTest().ToString("0") + "px fed=" + r.Fed +
               " drag=" + r.Dragging +
               " suck=" + _bowlBeingSucked + " speed=" + _suckSpeed.ToString("0") +
               " lockT=" + _lockT.ToString("0.0");
    }

